      hold = Date.now() + 2500;
      pick(i);
    }));
    pick(0);
    const tick = () => {
      if (!root.isConnected) return;
      if (!root.dataset.paused && Date.now() > hold) pick((idx + 1) % 3);
      setTimeout(tick, 2200);
    };
    setTimeout(tick, 1400);
  }

